-- Seeder dữ liệu demo V2; MySQL 8.4, UTF-8.
-- Không tạo bảng, không migrate; chọn database V2 trước khi chạy.
-- Revision: 20 distinct products, uploads/products, demo prices recalculated.
-- 8 category / 20 product / 20 image / 100 customer / 1000 order / 2705 item.
-- Chạy trong connection riêng, dừng khi lỗi; không dùng mysql --force.
-- Chạy lại bị từ chối (không phải JDBC loader NO_OP). Không xóa dữ liệu để chạy lại.
-- Helper procedure dưới đây là tên dành riêng của gói; cần CREATE ROUTINE/ALTER ROUTINE/EXECUTE.
-- Không tắt FK/unique checks. order_item_id do DB sinh.
SET @seed_sql_old_mode = @@SESSION.sql_mode;
SET @seed_sql_old_tz = @@SESSION.time_zone;
SET @seed_sql_old_charset = @@SESSION.character_set_client;
SET @seed_sql_old_results = @@SESSION.character_set_results;
SET @seed_sql_old_collation = @@SESSION.collation_connection;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_BACKSLASH_ESCAPES,NO_ENGINE_SUBSTITUTION';
SET SESSION time_zone = '+00:00';
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS `seed_v3_import_b48a7f2aab19`;
DELIMITER $$
CREATE PROCEDURE `seed_v3_import_b48a7f2aab19`()
SQL SECURITY INVOKER
BEGIN
  DECLARE v_lock INT DEFAULT 0;
  DECLARE v_release INT DEFAULT 0;
  DECLARE v_lock_name VARCHAR(64);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    IF v_lock = 1 THEN
      SELECT RELEASE_LOCK(v_lock_name) INTO v_release;
    END IF;
    SET SESSION sql_mode = @seed_sql_old_mode;
    SET SESSION time_zone = @seed_sql_old_tz;
    RESIGNAL;
  END;
  IF DATABASE() IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Select the target V2 database first';
  END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()
